1	// Pure-logic tests for the GDB Remote Serial Protocol encoders/parsers.
2	// The TCP transport is exercised by the round-trip e2e test.
3	
4	#include "hybrid/gdbstub_client.hpp"
5	
6	#define DOCTEST_CONFIG_IMPLEMENT_WITH_MAIN
7	#include <doctest.h>
8	
9	#include <cstdint>
10	#include <string>
