12	TEST_CASE("compute_checksum: mod-256 sum of ASCII bytes")
13	{
14	  // 'O'=0x4F, 'K'=0x4B; sum = 0x9A.
15	  CHECK(hybrid::gdbstub::compute_checksum("OK") == 0x9Au);
16	  CHECK(hybrid::gdbstub::compute_checksum("") == 0x00u);
17	  // 'c'=0x63.
18	  CHECK(hybrid::gdbstub::compute_checksum("c") == 0x63u);
19	}
20	
21	TEST_CASE("encode_packet wraps body with $...#cksum")
22	{
23	  CHECK(hybrid::gdbstub::encode_packet("OK") == "$OK#9a");
24	  CHECK(hybrid::gdbstub::encode_packet("c") == "$c#63");
25	}
26	
27	TEST_CASE("encode_p_packet writes reg_num in lowercase hex, value little-endian")
28	{
29	  // x1 = 0 -> "P1=" + 16 zeros.
30	  // 'P'=0x50, '1'=0x31, '='=0x3D, '0'×16 = 16*0x30 = 0x300.
31	  // 0x50 + 0x31 + 0x3D + 0x300 = 0x3BE -> 0xBE mod 256.
32	  CHECK(hybrid::gdbstub::encode_p_packet(1, 0u)
33	        == "$P1=0000000000000000#be");
34	}
35	
36	TEST_CASE("encode_p_packet emits little-endian byte order for 64-bit value")
37	{
38	  // 0xDEADBEEFCAFEBABE little-endian byte hex: be ba fe ca ef be ad de
39	  const auto pkt = hybrid::gdbstub::encode_p_packet(10, 0xDEADBEEFCAFEBABEULL);
40	  // Body looks like "Pa=bebafecaefbeadde"; just check the value substring.
41	  CHECK(pkt.find("Pa=bebafecaefbeadde") != std::string::npos);
42	  CHECK(pkt.starts_with("$"));
43	  CHECK(pkt.find("#") != std::string::npos);
44	}
45	
46	TEST_CASE("encode_p_packet uses two-digit hex for reg_num >= 16")
47	{
48	  // x16 -> "P10" (hex 0x10).
49	  const auto pkt = hybrid::gdbstub::encode_p_packet(16, 0u);
50	  CHECK(pkt.find("P10=") != std::string::npos);
51	}
52	
53	TEST_CASE("encode_p_packet uses three-digit hex for reg_num >= 256 - "
54	          "the previous two-nibble encoding silently aliased pmpaddr15 "
55	          "(reg 1025) onto reg 1 (ra) and corrupted the round-trip")
56	{
57	  const auto pkt = hybrid::gdbstub::encode_p_packet(1025, 0u);
58	  CHECK(pkt.find("P401=") != std::string::npos);
59	
60	  const auto pkt834 = hybrid::gdbstub::encode_p_packet(834, 0u);
61	  CHECK(pkt834.find("P342=") != std::string::npos);
62	}
63	
64	TEST_CASE("encode_continue is exactly $c#63")
65	{
66	  CHECK(hybrid::gdbstub::encode_continue() == "$c#63");
67	}
68	
69	TEST_CASE("parse_packet extracts body from $body#cksum framing")
70	{
71	  CHECK(hybrid::gdbstub::parse_packet("$OK#9a") == "OK");
72	  CHECK(hybrid::gdbstub::parse_packet("$#00") == "");
73	}
