75	TEST_CASE("parse_packet rejects malformed framing")
76	{
77	  CHECK_FALSE(hybrid::gdbstub::parse_packet("OK").has_value());
78	  CHECK_FALSE(hybrid::gdbstub::parse_packet("$OK").has_value());
79	  CHECK_FALSE(hybrid::gdbstub::parse_packet("$OK#").has_value());
