87	TEST_CASE("parse_feature_xml: unnumbered <reg> entries get sequential ids")
88	{
89	  using hybrid::gdbstub::parse_feature_xml;
90	
91	  hybrid::gdbstub::RegMap map;
92	  unsigned next = 0;
93	  parse_feature_xml(
94	    R"(<feature name="org.gnu.gdb.riscv.cpu">)"
95	    R"(<reg name="zero" bitsize="64"/>)"
96	    R"(<reg name="ra" bitsize="64"/>)"
97	    R"(<reg name="sp" bitsize="64"/>)"
98	    R"(</feature>)",
99	    map, next);
100	  CHECK(map.find("zero") == 0u);
101	  CHECK(map.find("ra")   == 1u);
102	  CHECK(map.find("sp")   == 2u);
103	  CHECK(next == 3u);
104	}
