106	TEST_CASE("parse_feature_xml: explicit regnum overrides sequential counter "
107	          "but resumes after the last seen entry")
108	{
109	  using hybrid::gdbstub::parse_feature_xml;
110	
111	  hybrid::gdbstub::RegMap map;
112	  unsigned next = 66;
113	  parse_feature_xml(
114	    R"(<feature name="org.gnu.gdb.riscv.csr">)"
115	    R"(<reg name="mstatus" bitsize="64" regnum="834" type="int"/>)"
116	    R"(<reg name="mepc" bitsize="64" regnum="897" type="int"/>)"
117	    R"(</feature>)",
118	    map, next);
119	  CHECK(map.find("mstatus") == 834u);
120	  CHECK(map.find("mepc")    == 897u);
121	}
