123	TEST_CASE("parse_feature_xml: ignores elements other than <reg>")
124	{
125	  using hybrid::gdbstub::parse_feature_xml;
126	
127	  hybrid::gdbstub::RegMap map;
128	  unsigned next = 0;
129	  parse_feature_xml(
