141	TEST_CASE("parse_target_xml extracts annex hrefs in declaration order")
142	{
143	  using hybrid::gdbstub::parse_target_xml;
144	  auto annexes = parse_target_xml(
145	    R"(<?xml version="1.0"?><target>)"
146	    R"(<architecture>riscv:rv64</architecture>)"
147	    R"(<xi:include href="riscv-64bit-cpu.xml"/>)"
