157	TEST_CASE("encode_p_body_bytes encodes variable-width payload "
158	          "in little-endian hex")
159	{
160	  // 4-byte payload {0xDE, 0xAD, 0xBE, 0xEF} at reg 5 -> "P5=deadbeef".
161	  const uint8_t bytes[] = {0xDE, 0xAD, 0xBE, 0xEF};
162	  const auto body = hybrid::gdbstub::encode_p_body_bytes(5, bytes, 4);
163	  CHECK(body == "P5=deadbeef");
